    inlines.length === 0
      ? [100, 20, 300]
      : inlines.length === 2
        ? [400, 100, 1000]
        : inlines.includes("start")
          ? [100, 100, 1000]
          : [850, 100, 1000];
  const chip = { top, right: left + width, bottom: top + 28, left };
